  @override
  String get legalDisclaimerRegulatoryBody =>
      'DVTech Ventures est une entreprise technologique et non un fournisseur de services juridiques réglementés. Nous ne sommes pas autorisés par la Solicitors Regulatory Authority (Royaume-Uni), le Bar Council of India, la Law Society of Kenya, aucun barreau d\'État américain ou tout autre organisme de réglementation juridique à fournir des services juridiques. La plateforme Umbrella ne propose pas d\'activité juridique réglementée telle que définie dans la loi sur les services juridiques de 2007 (Royaume-Uni) ou dans la législation équivalente dans d\'autres juridictions.';

