  @override
  String get legalDisclaimerScopeBody =>
      'Cette clause de non-responsabilité s\'applique à toutes les fonctionnalités de la plateforme Umbrella, y compris, mais sans s\'y limiter : le vérificateur de problèmes juridiques, AI Copilot, l\'examen de documents, la recherche juridique, l\'analyse de questions, les mémos stratégiques, les projets de documents et tout autre contenu généré par l\'IA. Elle s\'applique à tous les utilisateurs (consommateurs, utilisateurs avocats et locataires de cabinets d\'avocats) dans toutes les juridictions dans lesquelles Umbrella opère (Inde, États-Unis, Kenya et Royaume-Uni).';

