  @override
  String get legalPrivacyAutomatedBody =>
      'Umbrella utilise l\'IA pour générer des analyses juridiques, identifier les problèmes et suggérer des actions. Ces résultats de l\'IA sont uniquement informatifs et ne constituent pas des décisions contraignantes concernant vos droits légaux. Aucune décision entièrement automatisée ayant un effet juridique ou tout aussi important n’est prise à votre sujet sans examen humain. Notre évaluation des risques par l\'IA pour la détection des fraudes peut affecter l\'accès à la plateforme ; vous pouvez demander un examen humain d\'une telle décision.';

