  @override
  String get legalPrivacyCollectBillingBody =>
      'Données de facturation : plan d\'abonnement, type de mode de paiement (marque de la carte, quatre derniers chiffres), adresse de facturation et historique des transactions. Les détails complets de la carte de paiement sont traités par notre processeur de paiement conforme à la norme PCI-DSS (Stripe) et ne sont jamais stockés sur nos serveurs.';

  @override
  String get legalPrivacyCollectContentBody =>
      'Données de contenu : documents juridiques, descriptions de cas, notes d\'affaires, communications clients et résultats générés par l\'IA que vous créez ou soumettez via la plateforme. Ce contenu est traité pour fournir le service et n\'est pas utilisé pour la formation en IA sans votre consentement explicite.';

  @override
  String get legalPrivacyCollectCookiesBody =>
      'Cookies et suivi : nous utilisons des cookies de session strictement nécessaires, des cookies de préférences fonctionnelles et, avec votre consentement, des cookies d\'analyse (Vercel Analytics, Sentry error tracking). Vous pouvez gérer les préférences en matière de cookies via le panneau de paramètres des cookies.';

  @override
  String get legalPrivacyCollectDeviceBody =>
      'Données techniques et de l\'appareil : adresse IP, type de navigateur, système d\'exploitation, identifiants de l\'appareil, résolution de l\'écran et fuseau horaire. Utilisé pour la sécurité, la prévention de la fraude et la compatibilité des services.';

  @override
