  @override
  String get legalPrivacyCollectUsageBody =>
      'Données d\'utilisation : pages visitées, fonctionnalités utilisées, requêtes IA soumises, documents téléchargés, temps passé, événements de clic et enregistrements de session (lorsque le consentement est donné). Ces données sont collectées via des analyses de première partie.';

  @override
  String get legalPrivacyContactBody =>
      'Demandes de protection des données : support@odaflow.com. Nous visons à répondre dans les 10 jours ouvrables. Si vous n\'êtes pas satisfait de notre réponse, vous avez le droit de déposer une plainte auprès de votre autorité locale de protection des données : Royaume-Uni — ICO (ico.org.uk) ; UE : votre APD nationale ; Inde — Conseil indien de protection des données ; Kenya — Bureau du commissaire à la protection des données (odpc.go.ke).';

  @override
  String get legalPrivacyContactHeading => '14. Contactez-nous';

  @override
  String get legalPrivacyControllerBody =>
      'Umbrella est exploité par DVTech Ventures (« nous », « notre », « notre »). Nous agissons en tant que contrôleur de données pour les informations collectées auprès des consommateurs et en tant que sous-traitant pour les informations détenues au nom des locataires des cabinets d\'avocats. Adresse enregistrée et contact pour la protection des données : support@odaflow.com. Aux fins du RGPD, notre représentant UE/Royaume-Uni peut être contacté à la même adresse.';

  @override
  String get legalPrivacyControllerHeading => '1. Qui nous sommes';

  @override
  String get legalPrivacyCookiesBody =>
      'Les cookies strictement nécessaires (gestion de session, jetons de sécurité) sont toujours actifs. Les cookies fonctionnels (préférence de langue, thème) sont définis lors de la première utilisation et peuvent être effacés dans les paramètres du navigateur. Les cookies d\'analyse (Vercel, Sentry) ne sont déposés qu\'avec votre consentement via le bandeau cookie. Nous n\'utilisons pas de cookies publicitaires ou de suivi intersites.';

  @override
  String get legalPrivacyCookiesHeading => '12. Cookies';

  @override
  String get legalPrivacyDescription =>
      'Comment Umbrella collecte, utilise et protège vos informations. Cette politique s\'applique à tous les utilisateurs de parapluie.okaylegal.ai et des applications Umbrella associées en Inde, aux États-Unis, au Kenya et au Royaume-Uni.';

  @override
  String get legalPrivacyLegalBasisBody =>
      'Nous traitons les données personnelles selon les bases juridiques suivantes, en fonction de votre juridiction : (a) Contrat – traitement nécessaire à la fourniture des services pour lesquels vous avez souscrit ; (b) Intérêts légitimes : prévention de la fraude, sécurité de la plateforme, amélioration des produits ; (c) Consentement — Formation à l\'IA, e-mails marketing, cookies au-delà du strict nécessaire ; (d) Obligation légale – respect de la loi applicable. Pour l\'Inde, le traitement est régi par la loi de 2023 sur la protection des données personnelles numériques (loi DPDP). Pour le Royaume-Uni/l’UE, le traitement est conforme au RGPD du Royaume-Uni et au RGPD de l’UE. Pour le Kenya, le traitement est conforme à la loi sur la protection des données de 2019. Pour les utilisateurs américains, nous nous conformons aux lois de l\'État applicables en matière de confidentialité, notamment la CCPA/CPRA.';

  @override
  String get legalPrivacyLegalBasisHeading =>
      '2. Bases juridiques du traitement';

  @override
  String get legalPrivacyPolicy => 'politique de confidentialité';

  @override
  String get legalPrivacyRetentionBody =>
      'Nous conservons les données personnelles aussi longtemps que votre compte est actif. Lors de la suppression du compte, nous supprimons ou anonymisons les données personnelles dans les 30 jours, sauf lorsque la conservation est requise par la loi (par exemple, les enregistrements de facturation conservés pendant 7 ans à des fins de conformité fiscale, les journaux d\'audit conservés pendant 12 mois). Les locataires de l\'entreprise peuvent configurer des politiques de conservation personnalisées jusqu\'à 7 ans via les paramètres de gouvernance. Les ensembles de données de formation à l\'IA dérivés du contenu opté sont soumis au calendrier de conservation de notre Politique de consentement aux données et à l\'IA.';

  @override
  String get legalPrivacyRetentionHeading => '6. Rétention';

  @override
  String get legalPrivacyRightsCCPABody =>
      'Droits de la Californie (CCPA/CPRA) : droit de savoir quelles informations personnelles nous collectons ; droit de suppression ; droit de refuser la vente (nous ne vendons pas de données) ; droit à la non-discrimination dans l’exercice de ses droits ; droit de corriger des informations inexactes ; droit de limiter l’utilisation des informations personnelles sensibles.';

  @override
  String get legalPrivacyRightsDPDPBody =>
      'Droits de la loi DPDP en Inde : droit d\'accès, de rectification et d\'effacement de vos données personnelles numériques ; droit au règlement des griefs ; droit de désigner une personne pour exercer vos droits en votre nom. Contactez notre gestionnaire de consentement à support@odaflow.com.';

  @override
  String get legalPrivacyRightsGDPRBody =>
      'Droits GDPR / UK GDPR (utilisateurs de l’UE et du Royaume-Uni) : accès — obtenir une copie de vos données personnelles ; rectification — corriger les données inexactes ; effacement – demander la suppression (sous réserve de conservation légale) ; restriction : limiter le traitement pendant la résolution d\'un litige ; portabilité — recevez vos données dans un format lisible par machine ; objection — s\'opposer au traitement sur la base d\'intérêts légitimes ; décisions automatisées – ne pas être soumises uniquement à des décisions automatisées ayant des effets significatifs. Pour exercer ces droits, envoyez un e-mail à support@odaflow.com ou utilisez les paramètres de confidentialité de l\'application.';

